INSERT INTO politicas_publicas (title, description, bibliographicCitation, references_url, tipoID, instituicaoID, dominioID) VALUES ('Nº 121, DE 12 DE NOVEMBRO DE 2021', 'Substitui membro do Grupo de Trabalho de Gestão Energética - GTGE, instituído pela Resolução SIMA nº 62, de 02 de junho de 2021.', 'SÃO PAULO (Estado). Secretaria de Infraestrutura e Meio Ambiente. Resolução SIMA nº 121, de 12 de novembro de 2021. Substitui membro do Grupo de Trabalho de Gestão Energética - GTGE, instituído pela Resolução SIMA nº 62, de 02 de junho de 2021. Diário Oficial do Estado de São Paulo, São Paulo, SP, 13 nov 2021. Seção 1, p. 109.', 'https://www.imprensaoficial.com.br/DO/BuscaDO2001Documento_11_4.aspx?link=%2f2021%2fexecutivo+secao+i%2fnovembro%2f13%2fpag_0109_a47c7032490e26b03614e606b8297aff.pdf&pagina=109&data=13/11/2021&caderno=Executivo%20I&paginaordenacao=100109', 1, 1, 1);
INSERT INTO politicas_publicas (title, description, bibliographicCitation, references_url, tipoID, instituicaoID, dominioID) VALUES ('Nº 66.550, DE 07 DE MARÇO DE 2022', 'Reorganiza o “Programa Remanescentes Florestais”, de que tratam o artigo 23 da Lei nº. 13.798, de 9 de novembro de 2009, e os artigos 51 a 67 do Decreto nº. 55.947, de 24 de junho de 2010, passando a denominar-se “Programa REFLORESTA-SP”, e reorganiza o “Programa de Incentivos à Recuperação de Matas Ciliares e à Recomposição de Vegetação nas Bacias Formadoras de Mananciais de Água – Nascentes”, de que trata o Decreto nº. 62.914, de 8 de novembro de 2017, passando a denominar-se “Programa Nascentes”, e dá providências correlatas;', 'SÃO PAULO (Estado). Governo do Estado de São Paulo. Decreto nº. 66.550, de 07 de março de 2022.Reorganiza o “Programa Remanescentes Florestais”, de que tratam o artigo 23 da Lei nº. 13.798, de 9 de novembro de 2009, e os artigos 51 a 67 do Decreto nº. 55.947, de 24 de junho de 2010, passando a denominar-se “Programa REFLORESTA-SP”, e reorganiza o “Programa de Incentivos à Recuperação de Matas Ciliares e à Recomposição de Vegetação nas Bacias Formadoras de Mananciais de Água – Nascentes”, de que trata o Decreto nº. 62.914, de 8 de novembro de 2017, passando a denominar-se “Programa Nascentes”, e dá providências correlatas. Diário Oficial do Estado de São Paulo, 08 mar 2022 . Seção 1, p. 3.', 'https://www.al.sp.gov.br/repositorio/legislacao/decreto/2022/decreto-66550-07.03.2022.html', 2, 6, 1);
